import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.ClrTBeVd.js";const b=JSON.parse('{"title":"ui-forge 过程与审批","description":"","frontmatter":{"title":"ui-forge 过程与审批","outline":"deep","publish":true},"headers":[],"relativePath":"ai/ui-forge-process-approval.md","filePath":"ai/ui-forge-process-approval.md","lastUpdated":1790144657000}'),i={name:"ai/ui-forge-process-approval.md"};function o(n,e,l,d,p,h){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="ui-forge-过程与审批" tabindex="-1">ui-forge 过程与审批 <a class="header-anchor" href="#ui-forge-过程与审批" aria-label="Permalink to &quot;ui-forge 过程与审批&quot;">​</a></h1><p>任务执行时，用户既要看到 Codex 在做什么，也要在需要时回答问题、确认操作。这两件事使用同一条通信链路，但处理方式不同：过程消息用来展示，审批和提问需要校验后回复。</p><h2 id="执行过程如何展示" tabindex="-1">执行过程如何展示 <a class="header-anchor" href="#执行过程如何展示" aria-label="Permalink to &quot;执行过程如何展示&quot;">​</a></h2><p>Codex 会持续发送消息、命令输出和文件修改等进度。ui-forge 根据事件中的会话、轮次和执行项标识，找到需要更新的内容。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionEventHub.ts" target="_blank" rel="noreferrer">源码：事件路由与展示更新</a></p><table tabindex="0"><thead><tr><th>Codex 的操作</th><th>页面展示</th></tr></thead><tbody><tr><td>回复用户</td><td>回复正文</td></tr><tr><td>执行命令</td><td>工作目录、命令输出和退出码</td></tr><tr><td>修改文件</td><td>文件名称和修改差异</td></tr><tr><td>调用 MCP 工具</td><td>工具名称、返回结果或错误</td></tr><tr><td>制定或更新计划</td><td>计划步骤及完成状态</td></tr><tr><td>委派子任务</td><td>子任务信息及执行状态</td></tr></tbody></table><h2 id="审批请求如何往返" tabindex="-1">审批请求如何往返 <a class="header-anchor" href="#审批请求如何往返" aria-label="Permalink to &quot;审批请求如何往返&quot;">​</a></h2><p>以命令审批为例：</p><ol><li>Codex 发出 <code>item/commandExecution/requestApproval</code>，带上原生请求 ID 和待确认的操作。</li><li><code>codex-client</code> 保存请求，生成随机 <code>token</code>，Server 把它发送给所属任务的页面或 CLI。</li><li>用户选择决议，客户端提交任务 ID、token 和结果；如果是提问或表单，则提交填写的内容。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-webview/src/features/sessions/PendingRequestPanel.tsx" target="_blank" rel="noreferrer">源码：交互面板</a></li><li>后端校验通过后，用原始 <code>request.id</code> 将结果回传给 Codex，由 Codex 处理后续执行。</li></ol><p>ui-forge 负责传递用户决议，不会自行批准请求，也不在用户点“允许”后代替 Codex 执行命令。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionService.ts#L371" target="_blank" rel="noreferrer">源码：请求回复</a></p><h3 id="token-解决什么问题" tabindex="-1">token 解决什么问题 <a class="header-anchor" href="#token-解决什么问题" aria-label="Permalink to &quot;token 解决什么问题&quot;">​</a></h3><p>Codex 原生 <code>request.id</code> 只在当前连接内有效，新连接可能再次使用相同 ID。随机 token 将用户回复绑定到这一次请求，避免旧页面的回复误匹配新连接里的请求。</p><p>token 是这次待回复请求的标识，不是账号登录凭据。后端校验的重点是：</p><ol><li>token 还在当前连接的待回复表里。</li><li>请求属于当前任务，子线程也必须能追溯到主任务。</li><li>用户提交的结果符合这个请求对应的 Schema（数据格式约束）。</li><li>同一请求正在提交回复时，拒绝其他入口的重复提交；发送成功后移除请求，并通知各入口更新状态。</li></ol><p>这些检查依据当前连接中的真实请求，不依据页面上的按钮或展示缓存。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/packages/codex-client/src/codexClient.ts#L193" target="_blank" rel="noreferrer">源码：请求校验</a></p><h2 id="断线后-哪些审批还能处理" tabindex="-1">断线后，哪些审批还能处理 <a class="header-anchor" href="#断线后-哪些审批还能处理" aria-label="Permalink to &quot;断线后，哪些审批还能处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>重新打开时怎么处理</th></tr></thead><tbody><tr><td>只关闭页面，Server 和 Codex 连接仍在</td><td>从当前连接的 <code>pendingRequests()</code> 读取属于这个任务的待回复请求，放入重连快照</td></tr><tr><td>请求已由 CLI 处理，或已被 Codex 撤销</td><td>不再放入重连快照，旧页面提交的回复也会被拒绝</td></tr><tr><td>Server 或 Codex 进程已关闭</td><td>待回复表与 token 清空，历史记录不能用于重放授权</td></tr></tbody></table><p>所以，重连时恢复的是当前仍有效的请求，不是照搬历史审批卡片。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionEventHub.ts#L30" target="_blank" rel="noreferrer">源码：订阅时读取待回复请求</a></p><h2 id="审批有哪些权限边界" tabindex="-1">审批有哪些权限边界 <a class="header-anchor" href="#审批有哪些权限边界" aria-label="Permalink to &quot;审批有哪些权限边界&quot;">​</a></h2><p>VS Code 插件只允许在任务对应的项目中继续、停止或处理审批，并要求工作区已受信任。创建任务时，目标目录以当前工作区为准，不接受页面传入的其他目录。CLI 不经过这些插件检查，但仍受 Codex 的沙箱和审批策略限制。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/vscode-extension/src/hostRequestPolicy.ts" target="_blank" rel="noreferrer">源码：工作区检查</a></p><p>Server 的执行策略是：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  sandbox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workspace-write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  approvalPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;on-request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  approvalsReviewer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto_review&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>此外，Server 会将任务的临时产物目录加入可写范围。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/runtime/sessionPolicy.ts" target="_blank" rel="noreferrer">源码：执行策略</a></p><p>这不等于所有命令都要人工点击。Codex 按沙箱、审批策略和 reviewer 配置处理授权；只有实际发给客户端的请求，才由 ui-forge 展示并回传决议。设计规则和只读设计桥不额外授予执行权限。</p>`,23)])])}const u=t(i,[["render",o]]);export{b as __pageData,u as default};
